import React from 'react';
import './Marquee.css';
const items = ['HTML5','✦','CSS3','✦','SCSS','✦','JavaScript','✦','React','✦','Laravel','✦','Figma','✦','Bootstrap','✦','jQuery','✦','WordPress','✦','GA4','✦','GTM','✦','Photoshop','✦','GitHub','✦'];
export default function Marquee() {
  const doubled = [...items,...items];
  return (
    <div className="marquee-wrap">
      <div className="marquee-track">
        {doubled.map((t,i) => (
          <span key={i} className={t==='✦'?'msep':'mitem'}>{t}</span>
        ))}
      </div>
    </div>
  );
}
